class QuestProject extends DataClass implements Insertable<QuestProject> {
  final String questId;
  final String projectId;
  final int linkedAt;
  const QuestProject({
    required this.questId,
    required this.projectId,
    required this.linkedAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['quest_id'] = Variable<String>(questId);
    map['project_id'] = Variable<String>(projectId);
    map['linked_at'] = Variable<int>(linkedAt);
    return map;
  }

  QuestProjectsCompanion toCompanion(bool nullToAbsent) {
    return QuestProjectsCompanion(
      questId: Value(questId),
      projectId: Value(projectId),
      linkedAt: Value(linkedAt),
    );
  }

  factory QuestProject.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return QuestProject(
      questId: serializer.fromJson<String>(json['questId']),
      projectId: serializer.fromJson<String>(json['projectId']),
      linkedAt: serializer.fromJson<int>(json['linkedAt']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'questId': serializer.toJson<String>(questId),
      'projectId': serializer.toJson<String>(projectId),
      'linkedAt': serializer.toJson<int>(linkedAt),
    };
  }

  QuestProject copyWith({String? questId, String? projectId, int? linkedAt}) =>
      QuestProject(
        questId: questId ?? this.questId,
        projectId: projectId ?? this.projectId,
        linkedAt: linkedAt ?? this.linkedAt,
      );
  QuestProject copyWithCompanion(QuestProjectsCompanion data) {
    return QuestProject(
      questId: data.questId.present ? data.questId.value : this.questId,
      projectId: data.projectId.present ? data.projectId.value : this.projectId,
      linkedAt: data.linkedAt.present ? data.linkedAt.value : this.linkedAt,
    );
  }

  @override
  String toString() {
    return (StringBuffer('QuestProject(')
          ..write('questId: $questId, ')
          ..write('projectId: $projectId, ')
          ..write('linkedAt: $linkedAt')
          ..write(')'))
        .toString();
  }

  @override
  int get hashCode => Object.hash(questId, projectId, linkedAt);
  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      (other is QuestProject &&
          other.questId == this.questId &&
          other.projectId == this.projectId &&
          other.linkedAt == this.linkedAt);
}

