class $$ProfilesTableTableManager
    extends
        RootTableManager<
          _$ColonyDatabase,
          $ProfilesTable,
          Profile,
          $$ProfilesTableFilterComposer,
          $$ProfilesTableOrderingComposer,
          $$ProfilesTableAnnotationComposer,
          $$ProfilesTableCreateCompanionBuilder,
          $$ProfilesTableUpdateCompanionBuilder,
          (Profile, $$ProfilesTableReferences),
          Profile,
          PrefetchHooks Function({
            bool tasksRefs,
            bool needDefinitionsRefs,
            bool checkInsRefs,
            bool dailyReviewsRefs,
            bool weeklyReviewsRefs,
            bool workPrioritiesRefs,
            bool billsRefs,
            bool scheduleBlocksRefs,
            bool questsRefs,
            bool projectsRefs,
            bool decisionRecordsRefs,
            bool researchNodesRefs,
            bool learningSessionsRefs,
            bool researchEvidenceItemsRefs,
            bool financialEntitiesRefs,
            bool financialAccountsRefs,
            bool ledgerTransactionsRefs,
            bool healthConditionsRefs,
            bool symptomEntriesRefs,
            bool healthAppointmentsRefs,
            bool inventoryItemsRefs,
            bool peopleRefs,
            bool categoryBudgetsRefs,
            bool personInteractionsRefs,
            bool tripsRefs,
            bool organizationsRefs,
            bool homeMaintenanceTasksRefs,
            bool commitmentsRefs,
            bool contextZonesRefs,
            bool integrationConsentsRefs,
            bool externalCalendarEventsRefs,
            bool knowledgeAreasRefs,
            bool flashcardDecksRefs,
            bool flashcardsRefs,
            bool googleTimelineImportsRefs,
            bool googleTimelinePlaceLabelsRefs,
          })
        > {
  $$ProfilesTableTableManager(_$ColonyDatabase db, $ProfilesTable table)
    : super(
        TableManagerState(
          db: db,
          table: table,
          createFilteringComposer: () =>
              $$ProfilesTableFilterComposer($db: db, $table: table),
          createOrderingComposer: () =>
              $$ProfilesTableOrderingComposer($db: db, $table: table),
          createComputedFieldComposer: () =>
              $$ProfilesTableAnnotationComposer($db: db, $table: table),
          updateCompanionCallback:
              ({
                Value<String> id = const Value.absent(),
                Value<String> colonyName = const Value.absent(),
                Value<String> displayName = const Value.absent(),
                Value<String> timezone = const Value.absent(),
                Value<String> locale = const Value.absent(),
                Value<String> baseCurrency = const Value.absent(),
                Value<int> createdAt = const Value.absent(),
                Value<int> updatedAt = const Value.absent(),
                Value<int?> deletedAt = const Value.absent(),
                Value<int> version = const Value.absent(),
                Value<int> rowid = const Value.absent(),
              }) => ProfilesCompanion(
                id: id,
                colonyName: colonyName,
                displayName: displayName,
                timezone: timezone,
                locale: locale,
                baseCurrency: baseCurrency,
                createdAt: createdAt,
                updatedAt: updatedAt,
                deletedAt: deletedAt,
                version: version,
                rowid: rowid,
              ),
          createCompanionCallback:
              ({
                required String id,
                required String colonyName,
                required String displayName,
                required String timezone,
                required String locale,
                required String baseCurrency,
                required int createdAt,
                required int updatedAt,
                Value<int?> deletedAt = const Value.absent(),
                Value<int> version = const Value.absent(),
                Value<int> rowid = const Value.absent(),
              }) => ProfilesCompanion.insert(
                id: id,
                colonyName: colonyName,
                displayName: displayName,
                timezone: timezone,
                locale: locale,
                baseCurrency: baseCurrency,
                createdAt: createdAt,
                updatedAt: updatedAt,
                deletedAt: deletedAt,
                version: version,
                rowid: rowid,
              ),
          withReferenceMapper: (p0) => p0
              .map(
                (e) => (
                  e.readTable(table),
                  $$ProfilesTableReferences(db, table, e),
                ),
              )
              .toList(),
          prefetchHooksCallback:
              ({
                tasksRefs = false,
                needDefinitionsRefs = false,
                checkInsRefs = false,
                dailyReviewsRefs = false,
                weeklyReviewsRefs = false,
                workPrioritiesRefs = false,
                billsRefs = false,
                scheduleBlocksRefs = false,
                questsRefs = false,
                projectsRefs = false,
                decisionRecordsRefs = false,
                researchNodesRefs = false,
                learningSessionsRefs = false,
                researchEvidenceItemsRefs = false,
                financialEntitiesRefs = false,
                financialAccountsRefs = false,
                ledgerTransactionsRefs = false,
                healthConditionsRefs = false,
                symptomEntriesRefs = false,
                healthAppointmentsRefs = false,
                inventoryItemsRefs = false,
                peopleRefs = false,
                categoryBudgetsRefs = false,
                personInteractionsRefs = false,
                tripsRefs = false,
                organizationsRefs = false,
                homeMaintenanceTasksRefs = false,
                commitmentsRefs = false,
                contextZonesRefs = false,
                integrationConsentsRefs = false,
                externalCalendarEventsRefs = false,
                knowledgeAreasRefs = false,
                flashcardDecksRefs = false,
                flashcardsRefs = false,
                googleTimelineImportsRefs = false,
                googleTimelinePlaceLabelsRefs = false,
              }) {
                return PrefetchHooks(
                  db: db,
                  explicitlyWatchedTables: [
                    if (tasksRefs) db.tasks,
                    if (needDefinitionsRefs) db.needDefinitions,
                    if (checkInsRefs) db.checkIns,
                    if (dailyReviewsRefs) db.dailyReviews,
                    if (weeklyReviewsRefs) db.weeklyReviews,
                    if (workPrioritiesRefs) db.workPriorities,
                    if (billsRefs) db.bills,
                    if (scheduleBlocksRefs) db.scheduleBlocks,
