                    if (projectsRefs) db.projects,
                    if (decisionRecordsRefs) db.decisionRecords,
                    if (researchNodesRefs) db.researchNodes,
                    if (learningSessionsRefs) db.learningSessions,
                    if (researchEvidenceItemsRefs) db.researchEvidenceItems,
                    if (financialEntitiesRefs) db.financialEntities,
                    if (financialAccountsRefs) db.financialAccounts,
                    if (ledgerTransactionsRefs) db.ledgerTransactions,
                    if (healthConditionsRefs) db.healthConditions,
                    if (symptomEntriesRefs) db.symptomEntries,
                    if (healthAppointmentsRefs) db.healthAppointments,
                    if (inventoryItemsRefs) db.inventoryItems,
                    if (peopleRefs) db.people,
