final class $$NeedDefinitionsTableReferences
    extends
        BaseReferences<
          _$ColonyDatabase,
          $NeedDefinitionsTable,
          NeedDefinition
        > {
  $$NeedDefinitionsTableReferences(
    super.$_db,
    super.$_table,
    super.$_typedResult,
  );

  static $ProfilesTable _profileIdTable(_$ColonyDatabase db) =>
      db.profiles.createAlias(
        $_aliasNameGenerator(db.needDefinitions.profileId, db.profiles.id),
      );

  $$ProfilesTableProcessedTableManager get profileId {
    final $_column = $_itemColumn<String>('profile_id')!;

    final manager = $$ProfilesTableTableManager(
      $_db,
      $_db.profiles,
    ).filter((f) => f.id.sqlEquals($_column));
    final item = $_typedResult.readTableOrNull(_profileIdTable($_db));
    if (item == null) return manager;
    return ProcessedTableManager(
      manager.$state.copyWith(prefetchedData: [item]),
    );
  }

  static MultiTypedResultKey<$NeedReadingsTable, List<NeedReading>>
  _needReadingsRefsTable(_$ColonyDatabase db) => MultiTypedResultKey.fromTable(
    db.needReadings,
    aliasName: $_aliasNameGenerator(
      db.needDefinitions.id,
      db.needReadings.needId,
    ),
  );

  $$NeedReadingsTableProcessedTableManager get needReadingsRefs {
    final manager = $$NeedReadingsTableTableManager(
      $_db,
      $_db.needReadings,
    ).filter((f) => f.needId.id.sqlEquals($_itemColumn<String>('id')!));

    final cache = $_typedResult.readTableOrNull(_needReadingsRefsTable($_db));
    return ProcessedTableManager(
      manager.$state.copyWith(prefetchedData: cache),
    );
  }
}

