final class $$DecisionRecordsTableReferences
    extends
        BaseReferences<
          _$ColonyDatabase,
          $DecisionRecordsTable,
          DecisionRecord
        > {
  $$DecisionRecordsTableReferences(
    super.$_db,
    super.$_table,
    super.$_typedResult,
  );

  static $ProfilesTable _profileIdTable(_$ColonyDatabase db) =>
      db.profiles.createAlias(
        $_aliasNameGenerator(db.decisionRecords.profileId, db.profiles.id),
      );

  $$ProfilesTableProcessedTableManager get profileId {
    final $_column = $_itemColumn<String>('profile_id')!;

    final manager = $$ProfilesTableTableManager(
      $_db,
      $_db.profiles,
    ).filter((f) => f.id.sqlEquals($_column));
    final item = $_typedResult.readTableOrNull(_profileIdTable($_db));
    if (item == null) return manager;
    return ProcessedTableManager(
      manager.$state.copyWith(prefetchedData: [item]),
    );
  }

  static MultiTypedResultKey<$QuestDecisionsTable, List<QuestDecision>>
  _questDecisionsRefsTable(_$ColonyDatabase db) =>
      MultiTypedResultKey.fromTable(
        db.questDecisions,
        aliasName: $_aliasNameGenerator(
          db.decisionRecords.id,
          db.questDecisions.decisionId,
        ),
      );

  $$QuestDecisionsTableProcessedTableManager get questDecisionsRefs {
    final manager = $$QuestDecisionsTableTableManager(
      $_db,
      $_db.questDecisions,
    ).filter((f) => f.decisionId.id.sqlEquals($_itemColumn<String>('id')!));

    final cache = $_typedResult.readTableOrNull(_questDecisionsRefsTable($_db));
    return ProcessedTableManager(
      manager.$state.copyWith(prefetchedData: cache),
    );
  }
}

