                      if (researchEvidenceItemsRefs)
                        await $_getPrefetchedData<
                          LearningSessionRow,
                          $LearningSessionsTable,
                          ResearchEvidenceRow
                        >(
                          currentTable: table,
                          referencedTable: $$LearningSessionsTableReferences
