        > {
  $$HealthConditionsTableReferences(
    super.$_db,
    super.$_table,
    super.$_typedResult,
  );

  static $ProfilesTable _profileIdTable(_$ColonyDatabase db) =>
      db.profiles.createAlias(
        $_aliasNameGenerator(db.healthConditions.profileId, db.profiles.id),
      );

  $$ProfilesTableProcessedTableManager get profileId {
    final $_column = $_itemColumn<String>('profile_id')!;

    final manager = $$ProfilesTableTableManager(
      $_db,
      $_db.profiles,
    ).filter((f) => f.id.sqlEquals($_column));
    final item = $_typedResult.readTableOrNull(_profileIdTable($_db));
    if (item == null) return manager;
    return ProcessedTableManager(
      manager.$state.copyWith(prefetchedData: [item]),
    );
  }

  static MultiTypedResultKey<$SymptomEntriesTable, List<SymptomEntryRow>>
  _symptomEntriesRefsTable(_$ColonyDatabase db) =>
      MultiTypedResultKey.fromTable(
        db.symptomEntries,
        aliasName: $_aliasNameGenerator(
          db.healthConditions.id,
          db.symptomEntries.conditionId,
        ),
      );

  $$SymptomEntriesTableProcessedTableManager get symptomEntriesRefs {
    final manager = $$SymptomEntriesTableTableManager(
      $_db,
      $_db.symptomEntries,
    ).filter((f) => f.conditionId.id.sqlEquals($_itemColumn<String>('id')!));

    final cache = $_typedResult.readTableOrNull(_symptomEntriesRefsTable($_db));
    return ProcessedTableManager(
      manager.$state.copyWith(prefetchedData: cache),
    );
  }
}

